package io.github.deathcannon;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.Charset;
import java.util.HashMap;
import java.util.Map;

final class CacheFont
{
    private static final Charset CP1252 = Charset.forName("windows-1252");
    private static final int CELL = 24;
    private final BufferedImage mask;
    private final byte[] metrics;
    private final Map<Color, BufferedImage> colors = new HashMap<>();

    CacheFont(String name)
    {
        mask = DeathCannonOverlay.load("font-" + name + ".png");
        try (InputStream stream = CacheFont.class.getResourceAsStream("font-" + name + ".bin"))
        {
            if (stream == null)
            {
                throw new IOException("Missing font metrics");
            }
            metrics = stream.readAllBytes();
            if (metrics.length != 257 + 256 * 4)
            {
                throw new IOException("Invalid font metrics");
            }
        }
        catch (IOException ex)
        {
            throw new IllegalStateException("Could not load cache font " + name, ex);
        }
    }

    int width(String text)
    {
        return width(text.getBytes(CP1252));
    }

    private int width(byte[] text)
    {
        int width = 0;
        for (byte code : text)
        {
            width += Byte.toUnsignedInt(metrics[Byte.toUnsignedInt(code)]);
        }
        return width;
    }

    void draw(Graphics2D graphics, Color color, String value, int x, int y, double scale, int maxWidth,
        boolean centered)
    {
        byte[] text = value.getBytes(CP1252);
        int width = width(text);
        if (width == 0)
        {
            return;
        }
        double size = Math.min(scale, (double) maxWidth / width);
        BufferedImage atlas = colors.computeIfAbsent(color, this::tint);
        Graphics2D g = (Graphics2D) graphics.create();
        try
        {
            g.translate(centered ? Math.round(x - width * size / 2) : x, y);
            g.scale(size, size);
            int pen = 0;
            int ascent = Byte.toUnsignedInt(metrics[256]);
            for (byte code : text)
            {
                int id = Byte.toUnsignedInt(code);
                int offset = 257 + id * 4;
                int dx = pen + Byte.toUnsignedInt(metrics[offset]);
                int dy = Byte.toUnsignedInt(metrics[offset + 1]) - ascent;
                int w = Byte.toUnsignedInt(metrics[offset + 2]);
                int h = Byte.toUnsignedInt(metrics[offset + 3]);
                int sx = id % 16 * CELL;
                int sy = id / 16 * CELL;
                g.drawImage(atlas, dx, dy, dx + w, dy + h, sx, sy, sx + w, sy + h, null);
                pen += Byte.toUnsignedInt(metrics[id]);
            }
        }
        finally
        {
            g.dispose();
        }
    }

    private BufferedImage tint(Color color)
    {
        BufferedImage tinted = new BufferedImage(mask.getWidth(), mask.getHeight(), BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = tinted.createGraphics();
        try
        {
            g.drawImage(mask, 0, 0, null);
            g.setComposite(AlphaComposite.SrcIn);
            g.setColor(color);
            g.fillRect(0, 0, tinted.getWidth(), tinted.getHeight());
        }
        finally
        {
            g.dispose();
        }
        return tinted;
    }
}

package io.github.deathcannon;

import java.io.ByteArrayInputStream;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.util.Random;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import net.runelite.client.audio.AudioPlayer;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

final class CannonAudio
{
    private static final Logger LOG = LoggerFactory.getLogger(CannonAudio.class);
    private static final int RATE = 22050;
    private static final int BYTES_PER_SAMPLE = Short.BYTES;

    private final AudioPlayer player;
    private final ExecutorService worker = Executors.newSingleThreadExecutor(task ->
    {
        Thread thread = new Thread(task, "Hardcore Death Cannon audio");
        thread.setDaemon(true);
        return thread;
    });
    private final short[][] cues = new short[4][];

    CannonAudio(AudioPlayer player)
    {
        this.player = player;
    }

    void play(int volume, boolean cannonEnabled, boolean musicEnabled, int popupSeconds)
    {
        if (volume <= 0 || (!cannonEnabled && !musicEnabled))
        {
            return;
        }

        worker.execute(() ->
        {
            int mix = (cannonEnabled ? 1 : 0) | (musicEnabled ? 2 : 0);
            if (cues[mix] == null)
            {
                cues[mix] = synthesize(cannonEnabled, musicEnabled);
            }
            byte[] wav = encodeWave(cues[mix], volume, popupSeconds);
            if (Thread.currentThread().isInterrupted())
            {
                return;
            }
            try
            {
                player.play(new ByteArrayInputStream(wav), 0);
            }
            catch (Exception ex)
            {
                LOG.debug("Could not play the Hardcore Death Cannon cue", ex);
            }
        });
    }

    void close()
    {
        worker.shutdownNow();
    }

    static byte[] encodeWave(short[] samples, int volume, int popupSeconds)
    {
        int sampleCount = Math.min(samples.length, RATE * popupSeconds);
        int dataSize = sampleCount * BYTES_PER_SAMPLE;
        ByteBuffer wav = ByteBuffer.allocate(44 + dataSize).order(ByteOrder.LITTLE_ENDIAN);
        wav.put(new byte[] {'R', 'I', 'F', 'F'}).putInt(36 + dataSize);
        wav.put(new byte[] {'W', 'A', 'V', 'E', 'f', 'm', 't', ' '}).putInt(16);
        wav.putShort((short) 1).putShort((short) 1); // PCM, mono
        wav.putInt(RATE).putInt(RATE * BYTES_PER_SAMPLE);
        wav.putShort((short) BYTES_PER_SAMPLE).putShort((short) (8 * BYTES_PER_SAMPLE));
        wav.put(new byte[] {'d', 'a', 't', 'a'}).putInt(dataSize);
        for (int i = 0; i < sampleCount; i++)
        {
            wav.putShort((short) (samples[i] * Math.min(volume, 100) / 100));
        }
        return wav.array();
    }

    static short[] synthesize(boolean cannonEnabled, boolean musicEnabled)
    {
        short[] samples = new short[RATE * 33 / 10];
        Random random = new Random(2907);
        double rumble = 0;
        for (int i = 0; i < samples.length; i++)
        {
            double t = (double) i / RATE;
            double noise = random.nextDouble() * 2 - 1;
            rumble = 0.88 * rumble + 0.12 * noise;
            double cannon = 0.49 * Math.sin(2 * Math.PI * (42 * t + 3 * (1 - Math.exp(-t * 16))))
                * Math.exp(-t * 7) + 0.30 * rumble * Math.exp(-t * 5)
                + 0.29 * noise * Math.exp(-t * 65);
            double music = note(t - 0.34, 146.83, 0.66, 0.18)
                + note(t - 0.78, 174.61, 0.58, 0.16)
                + note(t - 1.12, 220.00, 0.68, 0.17)
                + note(t - 1.57, 207.65, 0.53, 0.16)
                + note(t - 1.92, 146.83, 1.34, 0.19)
                + note(t - 1.92, 110.00, 1.30, 0.10)
                + note(t - 1.92, 174.61, 1.25, 0.10);
            double mix = (cannonEnabled ? cannon : 0) + (musicEnabled ? music : 0);
            samples[i] = (short) Math.round(Math.tanh(mix) * Short.MAX_VALUE);
        }
        return samples;
    }

    private static double note(double time, double frequency, double length, double gain)
    {
        if (time <= 0 || time >= length)
        {
            return 0;
        }

        double envelope = Math.min(1, time / 0.048) * Math.pow(1 - time / length, 1.4);
        double phase = 2 * Math.PI * frequency * time;
        return gain * envelope * (Math.sin(phase) + 0.27 * Math.sin(2 * phase) + 0.12 * Math.sin(3 * phase));
    }
}

package io.github.deathcannon;

import java.math.BigDecimal;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class DeathBroadcast
{
    private static final String PLAYER_AND_LEVEL =
        "([a-z0-9 _-]{1,12})\\s*\\(((?:\\d{1,4}|\\d,\\d{3})|\\d(?:\\.\\d{1,3})?k)\\)";
    private static final String HIT = "(?:a|an) ([\\d,]+) damage hit\\b.*";
    private static final Pattern NAMED_KILLER = Pattern.compile(
        "(.+?) killed " + PLAYER_AND_LEVEL + " with " + HIT, Pattern.CASE_INSENSITIVE);
    private static final Pattern UNNAMED_KILLER = Pattern.compile(
        PLAYER_AND_LEVEL + " was killed by " + HIT, Pattern.CASE_INSENSITIVE);
    private static final Pattern COLOR_CODES = Pattern.compile("@[a-z_]+@", Pattern.CASE_INSENSITIVE);
    private static final Pattern TAGS = Pattern.compile("<[^>]*>");

    final String player;
    final String levelText;
    final int level;
    final String cause;
    final boolean lastSeen;
    final PlayerSighting sighting;
    volatile TopSkill topSkill;

    private DeathBroadcast(String player, String levelText, int level, String cause, PlayerSighting sighting, boolean lastSeen)
    {
        this.player = player;
        this.levelText = levelText;
        this.level = level;
        this.cause = cause;
        this.lastSeen = lastSeen;
        this.sighting = sighting;
    }

    DeathBroadcast withSighting(PlayerSighting sighting, boolean lastSeen)
    {
        return sighting == null ? this : new DeathBroadcast(player, levelText, level, cause, sighting, lastSeen);
    }

    static DeathBroadcast preview(String name, int level)
    {
        return new DeathBroadcast(name, Integer.toString(level), level, "Goblin (12 damage)", null, false);
    }

    static DeathBroadcast parse(String message)
    {
        String plain = plainText(message);
        Matcher match = NAMED_KILLER.matcher(plain);
        boolean named = match.matches();
        if (!named)
        {
            match = UNNAMED_KILLER.matcher(plain);
            if (!match.matches())
            {
                return null;
            }
        }

        int victim = named ? 2 : 1;
        String player = match.group(victim).trim();
        String display = match.group(victim + 1).toLowerCase(Locale.ROOT);
        String damage = match.group(victim + 2);
        String cause = named ? match.group(1).trim() + " (" + damage + " damage)" : damage + " damage hit";
        int level = display.endsWith("k")
            ? new BigDecimal(display.substring(0, display.length() - 1)).movePointRight(3).intValueExact()
            : Integer.parseInt(display.replace(",", ""));
        return player.isEmpty() || level <= 0 || level > 2376
            ? null : new DeathBroadcast(player, display, level, cause, null, false);
    }

    static String plainText(String message)
    {
        String plain = TAGS.matcher(message.replace("<br>", " ")).replaceAll("").replace('\u00a0', ' ');
        return COLOR_CODES.matcher(plain).replaceAll("").trim().replaceAll("\\s+", " ");
    }
}

