public final class DeathCannonPlugin extends Plugin
{
    private static final long SAVE_INTERVAL = TimeUnit.SECONDS.toNanos(30);
    private static final int CAPTURES_PER_FRAME = 2;
    private static final Logger LOG = LoggerFactory.getLogger(DeathCannonPlugin.class);

    @Inject private Client client;
    @Inject private DeathCannonConfig config;
    @Inject private OverlayManager overlayManager;
    @Inject private DeathCannonOverlay overlay;
    @Inject private ScheduledExecutorService executor;
    @Inject private AudioPlayer audioPlayer;
    @Inject private HiscoreClient hiscores;
    @Inject private ClientThread clientThread;
    @Inject private MouseManager mouseManager;

    private final ArrayDeque<DeathBroadcast> pending = new ArrayDeque<>();
    private final Map<String, DeathBroadcast> replays = new LinkedHashMap<>();
    private final MouseAdapter replayClicks = new MouseAdapter()
    {
        @Override
        public MouseEvent mouseClicked(MouseEvent event)
        {
            if (event.getButton() == MouseEvent.BUTTON1 && event.getModifiersEx() == 0)
            {
                int x = event.getX();
                int y = event.getY();
                clientThread.invokeLater(() -> replayAt(x, y));
            }
            return event;
        }
    };
    private final Map<String, Player> portraitRequests = new LinkedHashMap<>();
    private final Map<String, PlayerSighting> sightings = new LinkedHashMap<>(16, 0.75f, true);
    private final AtomicLong savedVersion = new AtomicLong();
    private long sightingVersion;
    private long submittedVersion;
    private long lastSaveAttempt;
    private Future<?> pendingSave;
    private boolean loadedSightings;
    private boolean seedPortraits;
    private CannonAudio audio;
    private volatile DeathBroadcast active;
    private volatile long startedAt;
    private volatile long durationMs;

    @Provides
    DeathCannonConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(DeathCannonConfig.class);
    }

    @Override
    protected synchronized void startUp()
    {
        audio = new CannonAudio(audioPlayer);
        if (!loadedSightings)
        {
            loadedSightings = true;
            executor.execute(this::loadSightings);
        }
        lastSaveAttempt = System.nanoTime();
        seedPortraits = true;
        overlayManager.add(overlay);
        overlay.loadGravestone();
        mouseManager.registerMouseListener(replayClicks);
    }

    private void loadSightings()
    {
        try
        {
            Map<String, PlayerSighting> restored = new SightingStore(getPluginDirectory()).load();
            synchronized (this)
            {
                sightings.forEach((key, sighting) -> restored.merge(key, sighting, SightingStore::newest));
                sightings.clear();
                restored.entrySet().stream()
                    .sorted(Map.Entry.comparingByValue((a, b) -> a.time.compareTo(b.time)))
                    .skip(Math.max(0, restored.size() - SightingStore.LIMIT))
                    .forEach(entry -> sightings.put(entry.getKey(), entry.getValue()));
            }
        }
        catch (IOException ex)
        {
            LOG.warn("Could not open the Hardcore Death Cannon cache directory", ex);
        }
    }

    @Override
    protected synchronized void shutDown()
    {
        saveSightings();
        pending.clear();
        replays.clear();
        portraitRequests.clear();
        active = null;
        overlayManager.remove(overlay);
        mouseManager.unregisterMouseListener(replayClicks);
        audio.close();
        audio = null;
    }

    @Subscribe
    public synchronized void onClientShutdown(ClientShutdown event)
    {
        Future<?> save = saveSightings();
        if (save != null)
        {
            event.waitFor(save);
        }
    }

    private Future<?> saveSightings()
    {
        if (sightingVersion <= savedVersion.get()
            || (submittedVersion == sightingVersion && pendingSave != null && !pendingSave.isDone()))
        {
            return pendingSave;
        }
        long version = sightingVersion;
        Map<String, PlayerSighting> snapshot = new LinkedHashMap<>(sightings);
        pendingSave = executor.submit(() ->
        {
            try
            {
                if (new SightingStore(getPluginDirectory()).save(snapshot))
                {
                    savedVersion.accumulateAndGet(version, Math::max);
                }
            }
            catch (IOException ex)
            {
                LOG.warn("Could not open the Hardcore Death Cannon cache directory", ex);
            }
        });
        submittedVersion = version;
        lastSaveAttempt = System.nanoTime();
        return pendingSave;
    }

    @Subscribe
    public synchronized void onChatMessage(ChatMessage event)
    {
        if (audio == null || client.getGameState() != GameState.LOGGED_IN
            || !client.getWorldType().contains(WorldType.HARDCORE_MAIN))
        {
            return;
        }

        if (event.getType() != ChatMessageType.BROADCAST && event.getType() != ChatMessageType.GAMEMESSAGE)
        {
            return;
        }

        DeathBroadcast death = DeathBroadcast.parse(event.getMessage());
        if (death != null && death.level > config.threshold())
        {
            PlayerSighting current = captureSighting(findPlayer(death.player));
            if (current != null)
            {
                remember(nameKey(death.player), current);
            }
            DeathBroadcast memorial = current != null ? death.withSighting(current, false)
                : death.withSighting(sightings.get(nameKey(death.player)), true);
            pending.add(memorial);
            playNext();
            rememberReplay(event.getMessage(), memorial);
            if (config.compactPopup())
            {
                return;
            }
            hiscores.lookupAsync(death.player.replace('_', ' '), HiscoreEndpoint.HARDCORE_MAIN)
                .whenComplete((result, error) ->
                {
                    if (error == null)
                    {
                        memorial.topSkill = TopSkill.fromHiscores(result);
                    }
                    else
                    {
                        LOG.debug("Could not look up the Hardcore Worlds top skill", error);
                    }
                });
        }
    }

    private void rememberReplay(String originalMessage, DeathBroadcast memorial)
    {
        String line = DeathBroadcast.plainText(originalMessage);
        replays.remove(line);
        replays.put(line, memorial);
        if (replays.size() > 100)
        {
            replays.remove(replays.keySet().iterator().next());
        }
    }

    private synchronized void replayAt(int x, int y)
    {
        if (audio == null || replays.isEmpty() || client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }
        Widget scroll = client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
        if (scroll == null || scroll.isHidden() || !scroll.getBounds().contains(x, y))
        {
            return;
        }
        Widget[] children = scroll.getDynamicChildren();
        if (children == null)
        {
            return;
        }
        for (Widget child : children)
        {
            if (child != null && !child.isHidden() && child.getBounds().contains(x, y))
            {
                String value = child.getText();
                if (value == null)
                {
                    continue;
                }
                String text = DeathBroadcast.plainText(value);
                DeathBroadcast memorial = replays.get(text);
                if (memorial == null)
                {
                    // Chat timestamp plugins can prefix the displayed message.
                    for (Map.Entry<String, DeathBroadcast> replay : replays.entrySet())
                    {
                        String original = replay.getKey();
                        if (text.endsWith(" " + original))
                        {
                            memorial = replay.getValue();
                            break;
                        }
                    }
                }
                if (memorial != null)
                {
                    active = null;
                    pending.addFirst(memorial);
                    playNext();
                    return;
                }
            }
        }
    }

    @Subscribe
    public synchronized void onCommandExecuted(CommandExecuted event)
    {
        if (audio != null && "deathcannon".equalsIgnoreCase(event.getCommand())
            && client.getGameState() == GameState.LOGGED_IN)
        {
            Player local = client.getLocalPlayer();
            if (local == null || local.getName() == null)
            {
                return;
            }
            DeathBroadcast preview = DeathBroadcast.preview(local.getName(), client.getTotalLevel())
                .withSighting(captureSighting(local), false);
            preview.topSkill = TopSkill.fromLocalPlayer(client);
            pending.add(preview);
            playNext();
        }
    }

    private Player findPlayer(String name)
    {
        Player local = client.getLocalPlayer();
        if (local == null)
        {
            return null;
        }
        String key = nameKey(name);
        if (key.equals(nameKey(local.getName())))
        {
            return local;
        }
        WorldView view = local.getWorldView();
        if (view != null)
        {
            for (Player player : view.players())
            {
                if (key.equals(nameKey(player.getName())))
                {
                    return player;
                }
            }
        }
        return null;
    }

    private static String nameKey(String name)
    {
        return name == null ? "" : name.replace('\u00a0', ' ').replace('_', ' ').trim().toLowerCase(Locale.ROOT);
    }

    @Subscribe
    public synchronized void onPlayerSpawned(PlayerSpawned event)
    {
        requestPortrait(event.getPlayer());
    }

    @Subscribe
    public synchronized void onPlayerChanged(PlayerChanged event)
    {
        requestPortrait(event.getPlayer());
    }

    @Subscribe
    public synchronized void onPlayerDespawned(PlayerDespawned event)
    {
        Player player = event.getPlayer();
        if (audio == null || client.getGameState() != GameState.LOGGED_IN
            || !client.getWorldType().contains(WorldType.HARDCORE_MAIN))
        {
            return;
        }
        String key = nameKey(player.getName());
        PlayerSighting previous = sightings.get(key);
        if (previous != null)
        {
            WorldPoint tile = sightingTile(player);
            if (tile != null)
            {
                remember(key, new PlayerSighting(previous.portrait, Instant.now(), client.getWorld(), tile));
            }
        }
    }

    private void requestPortrait(Player player)
    {
        if (audio != null && client.getWorldType().contains(WorldType.HARDCORE_MAIN))
        {
            String key = nameKey(player.getName());
            if (!key.isEmpty())
            {
                portraitRequests.put(key, player);
            }
        }
    }

    private void capturePortraits()
    {
        if (audio == null || client.getGameState() != GameState.LOGGED_IN
            || !client.getWorldType().contains(WorldType.HARDCORE_MAIN))
        {
            return;
        }
        if (seedPortraits)
        {
            Player local = client.getLocalPlayer();
            if (local != null && local.getWorldView() != null)
            {
                local.getWorldView().players().forEach(this::requestPortrait);
                seedPortraits = false;
            }
        }

        Iterator<Map.Entry<String, Player>> requests = portraitRequests.entrySet().iterator();
        for (int i = 0; i < CAPTURES_PER_FRAME && requests.hasNext(); i++)
        {
            Map.Entry<String, Player> request = requests.next();
            String key = request.getKey();
            PlayerSighting sighting = captureSighting(request.getValue());
            requests.remove();
            if (sighting != null)
            {
                remember(key, sighting);
            }
        }
    }

    private void remember(String key, PlayerSighting sighting)
    {
        sightings.put(key, sighting);
        sightingVersion++;
        if (sightings.size() > SightingStore.LIMIT)
        {
            sightings.remove(sightings.keySet().iterator().next());
        }
    }

    private PlayerSighting captureSighting(Player player)
    {
        BufferedImage portrait = capture(player);
        return portrait == null ? null : new PlayerSighting(portrait, Instant.now(), client.getWorld(),
            sightingTile(player));
    }

    private static WorldPoint sightingTile(Player player)
    {
        WorldPoint tile = player.getWorldLocation();
        WorldView view = player.getWorldView();
        if (tile != null && view != null && view.isInstance() && player.getLocalLocation() != null)
        {
            return WorldPoint.fromLocalInstance(view.getScene(), player.getLocalLocation(), tile.getPlane());
        }
        return tile;
    }

    @Subscribe
    public synchronized void onGameTick(GameTick event)
    {
        if (sightingVersion > savedVersion.get() && System.nanoTime() - lastSaveAttempt >= SAVE_INTERVAL)
        {
            saveSightings();
        }
    }

    private static BufferedImage capture(Player player)
    {
        if (player != null)
        {
            try
            {
                return PlayerPortrait.render(player.getModel());
            }
            catch (RuntimeException ex)
            {
                LOG.debug("Could not draw a Hardcore Death Cannon portrait", ex);
            }
        }
        return null;
    }

    @Subscribe
    public synchronized void onClientTick(ClientTick event)
    {
        capturePortraits();
        playNext();
    }

    @Subscribe
    public synchronized void onGameStateChanged(GameStateChanged event)
    {
        if (audio == null)
        {
            return;
        }
        switch (event.getGameState())
        {
            case HOPPING:
            case LOGIN_SCREEN:
            case CONNECTION_LOST:
                pending.clear();
                portraitRequests.clear();
                seedPortraits = true;
                active = null;
                break;
            default:
                break;
        }
    }

    private void playNext()
    {
        if (active != null && elapsedMs() < durationMs)
        {
            return;
        }

        DeathBroadcast next = pending.poll();
        if (next != null)
        {
            int popupSeconds = Math.max(1, Math.min(15, config.popupSeconds()));
            durationMs = TimeUnit.SECONDS.toMillis(popupSeconds);
            startedAt = System.nanoTime();
            audio.play(config.volume(), config.cannonSound(), config.memorialMusic(), popupSeconds);
        }
        active = next;
    }

    long durationMs()
    {
        return durationMs;
    }

    DeathBroadcast active()
    {
        return active;
    }

    long elapsedMs()
    {
        return (System.nanoTime() - startedAt) / 1_000_000;
    }
}

package io.github.deathcannon;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import net.runelite.api.JagexColor;
import net.runelite.api.Model;

final class PlayerPortrait
{
    static final int SIZE = 82;
    private static final double YAW = Math.toRadians(18);
    private static final double PITCH = Math.toRadians(9);

    private PlayerPortrait()
    {
    }

    // Draw a small, flat-shaded snapshot without changing the game's model or rasterizer.
    static BufferedImage render(Model model)
    {
        if (model == null || model.getVerticesCount() == 0 || model.getFaceCount() == 0)
        {
            return null;
        }

        int vertexCount = model.getVerticesCount();
        float[] x = model.getVerticesX();
        float[] y = model.getVerticesY();
        float[] z = model.getVerticesZ();
        double[] horizontal = new double[vertexCount];
        double[] vertical = new double[vertexCount];
        double[] depth = new double[vertexCount];
        double left = Double.POSITIVE_INFINITY;
        double right = Double.NEGATIVE_INFINITY;
        double top = Double.POSITIVE_INFINITY;
        double bottom = Double.NEGATIVE_INFINITY;
        for (int i = 0; i < vertexCount; i++)
        {
            double forward = z[i] * Math.cos(YAW) - x[i] * Math.sin(YAW);
            horizontal[i] = x[i] * Math.cos(YAW) + z[i] * Math.sin(YAW);
            vertical[i] = y[i] * Math.cos(PITCH) - forward * Math.sin(PITCH);
            depth[i] = forward * Math.cos(PITCH) + y[i] * Math.sin(PITCH);
            left = Math.min(left, horizontal[i]);
            right = Math.max(right, horizontal[i]);
            top = Math.min(top, vertical[i]);
            bottom = Math.max(bottom, vertical[i]);
        }

        double extent = Math.max(right - left, bottom - top);
        if (extent <= 0)
        {
            return null;
        }
        double scale = (SIZE - 8) / extent;
        int[] px = new int[vertexCount];
        int[] py = new int[vertexCount];
        for (int i = 0; i < vertexCount; i++)
        {
            px[i] = (int) Math.round(SIZE / 2.0 + (horizontal[i] - (left + right) / 2) * scale);
            py[i] = (int) Math.round(SIZE / 2.0 + (vertical[i] - (top + bottom) / 2) * scale);
        }

        int[] a = model.getFaceIndices1();
        int[] b = model.getFaceIndices2();
        int[] c = model.getFaceIndices3();
        int[] colors = model.getFaceColors1();
        int[] second = model.getFaceColors2();
        int[] third = model.getFaceColors3();
        byte[] transparency = model.getFaceTransparencies();
        short[] textures = model.getFaceTextures();
        List<Integer> faces = new ArrayList<>(model.getFaceCount());
        for (int face = 0; face < model.getFaceCount(); face++)
        {
            if (third[face] != -2 && (transparency == null || Byte.toUnsignedInt(transparency[face]) < 245))
            {
                faces.add(face);
            }
        }
        if (faces.isEmpty())
        {
            return null;
        }

        faces.sort(Comparator.<Integer>comparingDouble(
            face -> depth[a[face]] + depth[b[face]] + depth[c[face]]).reversed());
        BufferedImage portrait = new BufferedImage(SIZE, SIZE, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = portrait.createGraphics();
        try
        {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            int[] faceX = new int[3];
            int[] faceY = new int[3];
            for (int face : faces)
            {
                faceX[0] = px[a[face]];
                faceX[1] = px[b[face]];
                faceX[2] = px[c[face]];
                faceY[0] = py[a[face]];
                faceY[1] = py[b[face]];
                faceY[2] = py[c[face]];
                int alpha = transparency == null ? 255 : 255 - Byte.toUnsignedInt(transparency[face]);
                boolean textured = textures != null && textures[face] != -1;
                g.setColor(faceColor(colors[face], second[face], third[face], textured, alpha));
                g.fillPolygon(faceX, faceY, 3);
            }
        }
        finally
        {
            g.dispose();
        }
        return portrait;
    }

    private static Color faceColor(int first, int second, int third, boolean textured, int alpha)
    {
        int light = first & 127;
        if (third >= 0)
        {
            light = (light + (second & 127) + (third & 127)) / 3;
        }
        double luminance = (light + 0.5) / 128;
        double hue = (JagexColor.unpackHue((short) first) + 0.5) / 64;
        double saturation = textured ? 0 : (JagexColor.unpackSaturation((short) first) + 0.5) / 8;
        double amplitude = saturation * Math.min(luminance, 1 - luminance);
        return new Color(channel(0, hue, luminance, amplitude), channel(8, hue, luminance, amplitude),
            channel(4, hue, luminance, amplitude), alpha);
    }

    private static int channel(int offset, double hue, double luminance, double amplitude)
    {
        double k = (offset + hue * 12) % 12;
        double value = luminance - amplitude * Math.max(-1, Math.min(1, Math.min(k - 3, 9 - k)));
        return (int) Math.round(255 * value);
    }
}

package io.github.deathcannon;

import java.awt.image.BufferedImage;
import java.time.Instant;
import net.runelite.api.coords.WorldPoint;

final class PlayerSighting
{
    final BufferedImage portrait;
    final Instant time;
    final int world;
    final WorldPoint tile;

    PlayerSighting(BufferedImage portrait, Instant time, int world, WorldPoint tile)
    {
        this.portrait = portrait;
        this.time = time;
        this.world = world;
        this.tile = tile;
    }

    String displayLocation()
    {
        return WorldMapLabels.nearest(tile);
    }
}

package io.github.deathcannon;

import java.awt.image.BufferedImage;
import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.channels.FileLock;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.NoSuchFileException;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import java.util.zip.GZIPInputStream;
import java.util.zip.GZIPOutputStream;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.util.Filepath;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

final class SightingStore
{
    static final int LIMIT = 500;
    private static final int FORMAT = 0x48444301;
    private static final int SIZE = PlayerPortrait.SIZE;
    private static final Logger LOG = LoggerFactory.getLogger(SightingStore.class);
    private final Filepath file;

    SightingStore(Filepath directory)
    {
        file = directory.join("sightings.dat.gz");
    }

    Map<String, PlayerSighting> load()
    {
        Map<String, PlayerSighting> result = new LinkedHashMap<>();
        try (InputStream stream = file.openInputStream();
             DataInputStream in = new DataInputStream(new GZIPInputStream(stream)))
        {
            if (in.readInt() != FORMAT)
            {
                throw new IOException("Unknown sighting cache format");
            }
            int count = in.readInt();
            if (count < 0 || count > LIMIT)
            {
                throw new IOException("Invalid sighting cache size");
            }
            ByteBuffer packed = ByteBuffer.allocate(SIZE * SIZE * Integer.BYTES);
            int[] pixels = new int[SIZE * SIZE];
            for (int i = 0; i < count; i++)
            {
                String name = in.readUTF();
                Instant time = Instant.ofEpochMilli(in.readLong());
                int world = in.readInt();
                WorldPoint tile = in.readBoolean() ? new WorldPoint(in.readInt(), in.readInt(), in.readInt()) : null;
                in.readFully(packed.array());
                packed.asIntBuffer().get(pixels);
                BufferedImage portrait = new BufferedImage(SIZE, SIZE, BufferedImage.TYPE_INT_ARGB);
                portrait.setRGB(0, 0, SIZE, SIZE, pixels, 0, SIZE);
                result.put(name, new PlayerSighting(portrait, time, world, tile));
            }
        }
        catch (NoSuchFileException ignored)
        {
            // First launch.
        }
        catch (IOException ex)
        {
            LOG.warn("Could not read the Hardcore Death Cannon sighting cache", ex);
        }
        return result;
    }

    static PlayerSighting newest(PlayerSighting first, PlayerSighting second)
    {
        return first.time.isAfter(second.time) ? first : second;
    }

    // The lock and merge preserve newer sightings when two clients use the same cache.
    boolean save(Map<String, PlayerSighting> snapshot)
    {
        synchronized (SightingStore.class)
        {
            try
            {
                file.getParent().createDirectories();
                Filepath lockFile = file.getParent().join("sightings.lock");
                try (FileChannel channel = lockFile.openFileChannel(StandardOpenOption.CREATE, StandardOpenOption.WRITE);
                     FileLock lock = channel.lock())
                {
                    Map<String, PlayerSighting> combined = load();
                    snapshot.forEach((name, sighting) -> combined.merge(name, sighting, SightingStore::newest));
                    write(combined);
                }
                return true;
            }
            catch (IOException ex)
            {
                LOG.warn("Could not save the Hardcore Death Cannon sighting cache", ex);
                return false;
            }
        }
    }

    private void write(Map<String, PlayerSighting> sightings) throws IOException
    {
        List<Map.Entry<String, PlayerSighting>> newest = sightings.entrySet().stream()
            .sorted(Map.Entry.<String, PlayerSighting>comparingByValue((a, b) -> b.time.compareTo(a.time)))
            .limit(LIMIT)
            .collect(Collectors.toList());
        Filepath temporary = file.getParent().createTempFile("sightings-", ".tmp");
        try
        {
            try (DataOutputStream out = new DataOutputStream(new GZIPOutputStream(temporary.openOutputStream())))
            {
                out.writeInt(FORMAT);
                out.writeInt(newest.size());
                ByteBuffer packed = ByteBuffer.allocate(SIZE * SIZE * Integer.BYTES);
                int[] pixels = new int[SIZE * SIZE];
                // Write oldest first so the in-memory eviction order is preserved after launch.
                for (int i = newest.size() - 1; i >= 0; i--)
                {
                    Map.Entry<String, PlayerSighting> entry = newest.get(i);
                    out.writeUTF(entry.getKey());
                    PlayerSighting sighting = entry.getValue();
                    out.writeLong(sighting.time.toEpochMilli());
                    out.writeInt(sighting.world);
                    WorldPoint tile = sighting.tile;
                    out.writeBoolean(tile != null);
                    if (tile != null)
                    {
                        out.writeInt(tile.getX());
                        out.writeInt(tile.getY());
                        out.writeInt(tile.getPlane());
                    }
                    sighting.portrait.getRGB(0, 0, SIZE, SIZE, pixels, 0, SIZE);
                    packed.asIntBuffer().put(pixels);
                    out.write(packed.array());
                }
            }
            try
            {
                temporary.moveTo(file, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
            }
            catch (AtomicMoveNotSupportedException ex)
            {
                temporary.moveTo(file, StandardCopyOption.REPLACE_EXISTING);
            }
        }
        finally
        {
            temporary.deleteIfExists();
        }
    }
}

package io.github.deathcannon;

import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.client.hiscore.HiscoreResult;
import net.runelite.client.hiscore.HiscoreSkill;

final class TopSkill
{
    final Skill skill;
    final int level;
    private final long experience;

    private TopSkill(Skill skill, int level, long experience)
    {
        this.skill = skill;
        this.level = level;
        this.experience = experience;
    }

    static TopSkill fromHiscores(HiscoreResult result)
    {
        if (result == null)
        {
            return null;
        }
        TopSkill best = null;
        for (Skill skill : Skill.values())
        {
            net.runelite.client.hiscore.Skill ranked = result.getSkill(HiscoreSkill.valueOf(skill.name()));
            if (ranked != null)
            {
                best = choose(best, skill, ranked.getLevel(), ranked.getExperience());
            }
        }
        return best;
    }

    static TopSkill fromLocalPlayer(Client client)
    {
        TopSkill best = null;
        for (Skill skill : Skill.values())
        {
            best = choose(best, skill, client.getRealSkillLevel(skill), client.getSkillExperience(skill));
        }
        return best;
    }

    private static TopSkill choose(TopSkill best, Skill skill, int level, long experience)
    {
        return level > 0 && (best == null || level > best.level
            || (level == best.level && experience > best.experience)) ? new TopSkill(skill, level, experience) : best;
    }
}

package io.github.deathcannon;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.coords.WorldPoint;

final class WorldMapLabels
{
    private static final List<Label> LABELS = load();

    private WorldMapLabels()
    {
    }

    static String nearest(WorldPoint tile)
    {
        if (tile == null)
        {
            return "Unknown location";
        }

        Label best = null;
        double bestScore = Double.POSITIVE_INFINITY;
        for (Label label : LABELS)
        {
            if (tile.getPlane() < label.plane || tile.getPlane() >= label.plane + label.planes)
            {
                continue;
            }
            double distance = Math.hypot(tile.getX() - label.x, tile.getY() - label.y);
            int radius = label.scale == 0 ? 72 : label.scale == 1 ? 144 : 250;
            // Prefer towns and named areas over nearby river labels and minor landmarks.
            double score = distance + (label.scale == 1 ? -35 : label.scale >= 2 ? 75 : 0);
            if (distance <= radius && score < bestScore)
            {
                best = label;
                bestScore = score;
            }
        }
        return best == null ? "Unknown location" : best.name;
    }

    private static List<Label> load()
    {
        List<Label> labels = new ArrayList<>();
        try (InputStream stream = WorldMapLabels.class.getResourceAsStream("world-map-labels.tsv"))
        {
            if (stream == null)
            {
                throw new IOException("Missing world map labels");
            }
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream, StandardCharsets.UTF_8)))
            {
                String line;
                while ((line = reader.readLine()) != null)
                {
                    String[] fields = line.split("\t", 6);
                    labels.add(new Label(Integer.parseInt(fields[0]), Integer.parseInt(fields[1]),
                        Integer.parseInt(fields[2]), Integer.parseInt(fields[3]), Integer.parseInt(fields[4]),
                        fields[5].replace("<br>", " ")));
                }
            }
        }
        catch (IOException ex)
        {
            throw new IllegalStateException("Could not load cached world map labels", ex);
        }
        return labels;
    }

    private static final class Label
    {
        private final int x;
        private final int y;
        private final int plane;
        private final int planes;
        private final int scale;
        private final String name;

        private Label(int x, int y, int plane, int planes, int scale, String name)
        {
            this.x = x;
            this.y = y;
            this.plane = plane;
            this.planes = planes;
            this.scale = scale;
            this.name = name;
        }
    }
}

package io.github.deathcannon;

